('20260109', 'UPGRADE PANEL CONTROL LONG CRANE', 'Panel control crane sudah tidak sesuai standar dan downtime karena control crane', 'panel sudah tidak sesuai standar', 'panel sesuai standar dan meminimalisir downtime', 'perlu membeli panel baru 1 pcs', 'pengadaan panel untuk digunakan normalisasi', 'Pembuatan panel untuk normalisasi panel control secara berkala', 'meminimalisir downtime karena kerusakan control crane', 'pemasangan memerlukan waktu 2 jam', 'untuk menemukan trouble shooting lebih mudah, menghindari kabel short pada panel', 'perlu mematikan mesin crane untuk pemasangan panel control'),
('20260106', 'UPGRADE PANEL CONTROL MESIN TRUSS', '*) Banyak panel mesin yang kotor dan kurang rapi\n*) Jalur kontrol di setiap panel berbeda-beda, yang menyebabkan penanganan lama', 'Banyak panel yang kotor dan jalur kabel yang berantakan', '*) Bentuk panel distandartkan untuk semua mesin\n*) Setiap kabel diberi label disetiap jalurnya', '*) Bentuk panel dan jalur kabel yang seragam di semua mesin truss', '*) Normalisasi panel dan jalur kabel semua mesin truss', 'Normalisasi panel dan jalur kabel semua mesin truss', '*) Mempercepat penanganan jika terjadi kerusakan pada panel kontrol mesin', '*)Pemasangan harus kondisi mesin dimatikan selama 1 shift', '*)Jalur kabel lebih rapi dan tidaka ada lagi kabel yang berantakan', 'Pengerjaan bertahap karena jumlah mesin yang banyak'),
('20260628', 'UPGRADE PANEL DECOILER AUTO', 'Panel control decoiler terkena oli dan kabel mudah tertarik karena control di pintu.', 'Panel terletak di pintu decoiler.', 'Upgrade panel dan merubah posisi penempatan panel.', 'Kebutuhan part dan membutuhkan wkatu untuk modif panel.', 'Upgrade panel', 'Upgrade panel decoiler agar tidak terkena oli / kabel akrena tertarik dan suhu panas oli', '*) Mengurangi downtime karena kabel kontrol tertarik \n*) Suhu panel lebih dingin', '*) Membutuhkan waktu dan biaya', '*) Downtime karena decoiler berkurang dan mesin mencapai target', 'Membutuhkan waktu dan biaya'),
('20250609', 'UPGRADE SENSOR POTONG', 'Terlalu banyak jenis sensor pisau yang terpasang pada mesin', 'Beberapa mesin masih menggunakan sensor bawaan mesin', 'Semua jenis disamakan menjadi 1 type sensor', 'Untuk sensor pisau hanya perlu stock 1 type sensor', 'Standarnisasi sensor', 'Standarnisasi sensor', '*) Mengurangi jumlah type stock sensor', '*) Meningkatnya QTY permintaan sensor pisau', '*) Opname stock sensor pisau lebih mudah karena hanya ada 1 type sensor', 'Meningkatnya jumlah QTY permintaan sensor pisau'),
('20260629', 'UPGRADE WHEEL BLOX CRANE', 'Panel sudah mulai usang dan jalur kabel conrol berantakan', 'Menggunakan panel bawaan crane', 'Upgrade panel', 'Pengadaan part dan biaya', 'Upgrade panel long crane', 'Upgrade panel long crane secara bertahap', 'Panel lebih rapi dan mempercepat trouble shoot', 'Memerlukan waktu dan pengadaan part', 'Ketersediaan crane tercapai mempercepat pengiriman dan proses produksi', 'Memerlukan waktu dan biaya'),
('20250714', 'UPSPEED MESIN ATAP', 'Kesulitan setting speed dan terlalu banyak penggunaan valve', 'Penggerak forward reverse kr5 menggunakan fluida sehingga menyulitkan setting speed mesin', 'Penggerak forward reverse kr5 menggunakan motor gearbox yang di kontrol menggunakan inverter', 'Pengadaan sparepart yang mahal', 'Data kebutuhan sparepart', 'Penggantian penggerak dari fluida ke gearbox sudah selesai 3 mesin, lanjut pengadaan', 'Mempermudah up speed dan efisiensi penggunaan oli dan valve, up speed mesin 6m; dari 18 detik ke 13 detik', 'Perlu waktu 1 hari untuk penggantian gearbox dan 1 hari untuk trial eror', 'Pemenuhan order customer', 'Penggantian memakan waktu'),
