DELIMITER $$
CREATE TRIGGER `after_delete_cost_breakdown` AFTER DELETE ON `cost_breakdown` FOR EACH ROW BEGIN
    UPDATE projects p
    SET p.planned_budget = COALESCE((SELECT SUM(planned_cost) FROM cost_breakdown WHERE project_id = OLD.project_id), 0),
        p.expenditure    = COALESCE((SELECT SUM(actual_cost)   FROM cost_breakdown WHERE project_id = OLD.project_id), 0),
        p.accumulation   = p.planned_budget - p.expenditure
    WHERE p.id = OLD.project_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_insert_cost_breakdown` AFTER INSERT ON `cost_breakdown` FOR EACH ROW BEGIN
    UPDATE projects p
    SET p.planned_budget = COALESCE((SELECT SUM(planned_cost) FROM cost_breakdown WHERE project_id = NEW.project_id), 0),
        p.expenditure    = COALESCE((SELECT SUM(actual_cost)   FROM cost_breakdown WHERE project_id = NEW.project_id), 0),
        p.accumulation   = p.planned_budget - p.expenditure
    WHERE p.id = NEW.project_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_update_cost_breakdown` AFTER UPDATE ON `cost_breakdown` FOR EACH ROW BEGIN
    -- Update project baru (jika project_id berubah, update yang baru)
    UPDATE projects p
    SET p.planned_budget = COALESCE((SELECT SUM(planned_cost) FROM cost_breakdown WHERE project_id = NEW.project_id), 0),
        p.expenditure    = COALESCE((SELECT SUM(actual_cost)   FROM cost_breakdown WHERE project_id = NEW.project_id), 0),
        p.accumulation   = p.planned_budget - p.expenditure
    WHERE p.id = NEW.project_id;

    -- Jika project_id berubah, update project lama juga
    IF NEW.project_id != OLD.project_id THEN
        UPDATE projects p
        SET p.planned_budget = COALESCE((SELECT SUM(planned_cost) FROM cost_breakdown WHERE project_id = OLD.project_id), 0),
            p.expenditure    = COALESCE((SELECT SUM(actual_cost)   FROM cost_breakdown WHERE project_id = OLD.project_id), 0),
            p.accumulation   = p.planned_budget - p.expenditure
        WHERE p.id = OLD.project_id;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `before_insert_cost_breakdown` BEFORE INSERT ON `cost_breakdown` FOR EACH ROW BEGIN
    SET NEW.planned_cost = COALESCE(NEW.planned_quantity, 0) * COALESCE(NEW.price_per_unit, 0);
    SET NEW.actual_cost   = COALESCE(NEW.actual_quantity, 0) * COALESCE(NEW.actual_price, 0);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `before_update_cost_breakdown` BEFORE UPDATE ON `cost_breakdown` FOR EACH ROW BEGIN
    IF NEW.planned_quantity != OLD.planned_quantity OR NEW.price_per_unit != OLD.price_per_unit THEN
        SET NEW.planned_cost = COALESCE(NEW.planned_quantity, 0) * COALESCE(NEW.price_per_unit, 0);
    END IF;
    IF NEW.actual_quantity != OLD.actual_quantity OR NEW.actual_price != OLD.actual_price THEN
        SET NEW.actual_cost = COALESCE(NEW.actual_quantity, 0) * COALESCE(NEW.actual_price, 0);
    END IF;
END
$$
DELIMITER ;

