--
-- Structure for view `v_milestone_status`
--
DROP TABLE IF EXISTS `v_milestone_status`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_milestone_status`  AS SELECT `m`.`id` AS `id`, `m`.`name` AS `name`, `m`.`sort_order` AS `sort_order`, count(`t`.`id`) AS `total_timelines`, sum(`t`.`verified`) AS `verified_timelines`, CASE WHEN count(`t`.`id`) = sum(`t`.`verified`) THEN 'green' ELSE 'red' END AS `status_color`, CASE WHEN count(`t`.`id`) = sum(`t`.`verified`) THEN '✔️' ELSE '✖️' END AS `status_icon` FROM (`ref_milestone` `m` left join `timelines` `t` on(`m`.`id` = `t`.`milestone_id`)) GROUP BY `m`.`id`, `m`.`name`, `m`.`sort_order` ORDER BY `m`.`sort_order` ASC ;

