DROP TABLE IF EXISTS `v_project_full`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `v_project_full`  AS SELECT `p`.`id` AS `id`, `p`.`project_name` AS `project_name`, `p`.`pic` AS `pic`, `st`.`name` AS `status_name`, `cat`.`name` AS `category_name`, `ben`.`name` AS `benefit_name`, `pr`.`name` AS `priority_name`, `p`.`start_date` AS `start_date`, `p`.`end_date` AS `end_date`, coalesce((select sum(`cb`.`actual_cost`) from `cost_breakdown` `cb` where `cb`.`project_id` = `p`.`id`),0) AS `actual_cost`, coalesce((select sum(`cb`.`planned_cost`) from `cost_breakdown` `cb` where `cb`.`project_id` = `p`.`id`),0) AS `planned_budget`, coalesce((select sum(`cb`.`planned_cost`) from `cost_breakdown` `cb` where `cb`.`project_id` = `p`.`id`),0) - coalesce((select sum(`cb`.`actual_cost`) from `cost_breakdown` `cb` where `cb`.`project_id` = `p`.`id`),0) AS `profit`, (select count(0) from `project_activities` `pa` where `pa`.`project_id` = `p`.`id`) AS `total_updates`, (select max(`pa`.`date`) from `project_activities` `pa` where `pa`.`project_id` = `p`.`id`) AS `last_update_date`, to_days(curdate()) - to_days(coalesce((select max(`pa`.`date`) from `project_activities` `pa` where `pa`.`project_id` = `p`.`id`),`p`.`start_date`)) AS `days_since_last_update`, `p`.`expenditure` AS `cost_amount`, NULL AS `responsible_person_name` FROM ((((`projects` `p` left join `ref_status` `st` on(`p`.`status_id` = `st`.`id`)) left join `ref_category` `cat` on(`p`.`category_id` = `cat`.`id`)) left join `ref_benefit` `ben` on(`p`.`benefit_id` = `ben`.`id`)) left join `ref_priority` `pr` on(`p`.`priority_id` = `pr`.`id`)) ;

